ARTICLES = [
 {'id':'loan-status','title':'Checking a loan application status','category':'application','keywords':['application','status','tracking','approved','pending'], 'content':'To check a loan application, use the lender official app or website and its application reference number. This demo cannot access personal applications or confirm approval. If the official channel does not show an update, contact the lender using contact details published on its official website.'},
 {'id':'documents','title':'Common loan application documents','category':'documents','keywords':['documents','KYC','PAN','identity','address','proof'], 'content':'A lender may request identity proof, address proof, income proof, bank statements, and tax identification documents. Requirements vary by lender and product. Submit documents only through a verified official channel and never share OTPs or passwords with an agent.'},
 {'id':'eligibility','title':'General loan eligibility factors','category':'eligibility','keywords':['eligible','eligibility','income','credit score','age'], 'content':'Lenders may consider age, income stability, existing obligations, credit history, and product-specific criteria. Exact requirements vary. This demo cannot assess a real person or promise approval.'},
 {'id':'repayment','title':'Understanding repayment schedules','category':'repayment','keywords':['repayment','schedule','EMI','installment','due date'], 'content':'A repayment schedule typically lists due dates, installment amounts, principal, interest, and remaining balance. Refer to the official sanction letter or lender account portal for the authoritative schedule. This demo cannot retrieve or calculate a customer-specific EMI.'},
 {'id':'payment-failed','title':'Troubleshooting a failed payment','category':'payments','keywords':['payment','failed','deducted','transaction','receipt'], 'content':'If a payment fails, save the transaction reference and check the bank or payment provider status. Avoid retrying repeatedly if funds appear deducted. Contact the lender and payment provider through official channels with the reference. Never share a PIN, password, or OTP.'},
 {'id':'payment-deducted','title':'Payment deducted but not reflected','category':'payments','keywords':['deducted','not reflected','pending','settlement','payment'], 'content':'Payment posting may take time depending on the payment channel. Keep the transaction reference and receipt, check the official account portal, and contact support if the payment remains unreflected beyond the timeframe stated by your provider. This demo cannot inspect real transactions.'},
 {'id':'fraud','title':'Reporting suspected fraud or unauthorized activity','category':'security','keywords':['fraud','unauthorized','scam','stolen','suspicious'], 'content':'For suspected fraud or unauthorized activity, contact your bank or lender immediately using the official app, website, or the number printed on your card or statement. Secure your accounts and follow the institution’s reporting process. Do not share OTPs, PINs, passwords, or full card details. This demo cannot freeze accounts or file a real report.'},
 {'id':'privacy','title':'Protecting personal and financial information','category':'security','keywords':['privacy','data','personal information','OTP','password','security'], 'content':'Use only verified official channels for sensitive documents. Never disclose OTPs, PINs, passwords, full card credentials, or remote-access codes to an unsolicited caller or chat. Review privacy notices before submitting personal information.'},
 {'id':'complaint','title':'Submitting a complaint or grievance','category':'support','keywords':['complaint','grievance','escalate','dispute','resolution'], 'content':'Use the lender’s official grievance or complaint channel, describe the issue, include relevant reference numbers, and retain the complaint acknowledgement. Escalation routes and timelines depend on the institution and applicable rules. This demo can create only a local sample escalation, not a real complaint.'},
 {'id':'contact-support','title':'Contacting customer support','category':'support','keywords':['support','contact','agent','human','representative'], 'content':'Contact the lender through the official app, website, or verified contact details on statements. Explain the issue and keep the case or interaction reference. This demo can record a simulated handoff but does not contact a live support team.'},
 {'id':'interest','title':'Understanding loan interest and fees','category':'loan-basics','keywords':['interest','fees','charges','APR','rate'], 'content':'Review the lender’s official Key Facts Statement, sanction letter, and loan agreement for the applicable interest rate, fees, penalties, and annualized cost disclosures. Rates and fees vary by product and customer. This demo cannot quote a personalized offer.'},
 {'id':'prepayment','title':'Prepayment and foreclosure questions','category':'repayment','keywords':['prepayment','foreclosure','close loan','early repayment'], 'content':'Prepayment and foreclosure conditions depend on the loan agreement, lender policy, product, and applicable rules. Check the agreement and request a written payoff statement through the official lender channel before making a decision.'},
]
